using CodigoActivo.Domain.Events;
using CodigoActivo.Domain.Users;
using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;

namespace CodigoActivo.Infrastructure.Events;

/// <summary>
/// Defines the Entity Framework mapping for the changes of the terms decisions.
/// </summary>
public sealed class TermsDecisionChangeConfiguration : IEntityTypeConfiguration<TermsDecisionChange>
{
    /// <summary>
    /// Name of the shadow key, generated by the database in insertion order, which also orders
    /// the changes made at the same instant.
    /// </summary>
    public const string Sequence = "Id";

    /// <summary>
    /// Configures the database mapping for the changes of the terms decisions.
    /// </summary>
    /// <param name="builder">Entity Framework builder used to configure the mapped type.</param>
    public void Configure(EntityTypeBuilder<TermsDecisionChange> builder)
    {
        builder.Property<long>(Sequence).ValueGeneratedOnAdd();
        builder.HasKey(Sequence);

        builder.Property(x => x.Accepted).IsRequired();
        builder.Property(x => x.ChangedAt).IsRequired();

        builder
            .HasOne<EventTermsAcceptance>()
            .WithMany(x => x.Changes)
            .HasForeignKey(x => new
            {
                x.EventId,
                x.UserId,
                x.TermsDocumentId,
            })
            .OnDelete(DeleteBehavior.Cascade);

        builder
            .HasOne<User>()
            .WithMany()
            .HasForeignKey(x => x.DecidedById)
            .OnDelete(DeleteBehavior.Cascade);

        builder
            .HasOne<User>()
            .WithMany()
            .HasForeignKey(x => x.RecordedById)
            .OnDelete(DeleteBehavior.Restrict);
    }
}
